import type { PlanFeature } from '@contracts/identity';
import type {
  Currency,
  PlanPeriodicity,
  UsageMetric,
} from '@contracts/billing';

/** Limit of a metric in a plan and, if billed per unit, its price in minor units. */
export interface PlanQuota {
  readonly metric: UsageMetric;
  readonly limit: number;
  readonly unitPriceMinor?: number;
}

/** State of a catalog plan. `code` is stable across environments; `id` is generated by each catalog. */
export interface PlanState {
  readonly id: string;
  readonly code: string;
  readonly name: string;
  readonly priceMinor: number;
  readonly currency: Currency;
  readonly periodicity: PlanPeriodicity;
  readonly quotas: readonly PlanQuota[];
  readonly features: readonly PlanFeature[];
}

/** A catalog plan: fixed price per period, quotas per metric and features. */
export class Plan {
  private constructor(private readonly state: PlanState) {}

  static of(state: PlanState): Plan {
    return new Plan(state);
  }

  get id(): string {
    return this.state.id;
  }

  snapshot(): PlanState {
    return this.state;
  }

  /** The metric limit, or `undefined` if the plan does not limit it. */
  limitOf(metric: UsageMetric): number | undefined {
    return this.state.quotas.find((quota) => quota.metric === metric)?.limit;
  }
}
